#!/usr/bin/env node
// Drift check for plugins/withReleaseSigning.js: confirms the live,
// gitignored android/app/build.gradle and android/build.gradle are exactly
// what the plugin's own transform functions would produce right now — not
// just "close enough" from when they were last hand-patched.
//
// Why this needs to exist at all: android/ is regenerated by `expo prebuild`
// and gitignored, so there's no committed copy to `git diff` against. And the
// plugin's own `// @generated` marker means a plain (non-clean) `expo
// prebuild` skips re-applying an already-present block — so after editing
// this plugin, the live files have to be hand-patched to match (a `--clean`
// prebuild would do it automatically, but this project has other
// hand-maintained native/ edits that don't survive `--clean`; see
// docs/HANDOFF.md). Hand-patching is exactly the kind of step that silently
// drifts from the source of truth over time. This script is the check: since
// both patch functions are idempotent (marker-guarded), re-running a
// function against its own already-patched output must be a no-op — if it
// isn't, the live file doesn't match what the plugin actually generates.
//
// Run after any edit to withReleaseSigning.js and after hand-patching
// android/ to match: `node scripts/verify-release-signing.js`

const fs = require("fs");
const path = require("path");
const { patchAppBuildGradle, patchRootBuildGradle } = require("../plugins/withReleaseSigning.js");

const ROOT = path.join(__dirname, "..");
const APP_GRADLE = path.join(ROOT, "android/app/build.gradle");
const ROOT_GRADLE = path.join(ROOT, "android/build.gradle");

let failed = false;

function check(label, file, patchFn) {
  if (!fs.existsSync(file)) {
    console.log(`  skip: ${label} — ${path.relative(ROOT, file)} does not exist (no prebuild yet?)`);
    return;
  }
  const live = fs.readFileSync(file, "utf8");
  const rePatched = patchFn(live);
  if (rePatched === live) {
    console.log(`  ok:   ${label} matches what the plugin generates`);
  } else {
    failed = true;
    console.log(`  FAIL: ${label} does NOT match what the plugin generates — drift detected in ${path.relative(ROOT, file)}`);
    const liveLines = live.split("\n");
    const patchedLines = rePatched.split("\n");
    for (let i = 0; i < Math.max(liveLines.length, patchedLines.length); i++) {
      if (liveLines[i] !== patchedLines[i]) {
        console.log(`        first diff at line ${i + 1}:`);
        console.log(`          live:    ${JSON.stringify(liveLines[i] ?? "<eof>")}`);
        console.log(`          plugin:  ${JSON.stringify(patchedLines[i] ?? "<eof>")}`);
        break;
      }
    }
  }
}

console.log("Verifying android/ matches plugins/withReleaseSigning.js...");
check("android/app/build.gradle", APP_GRADLE, patchAppBuildGradle);
check("android/build.gradle", ROOT_GRADLE, patchRootBuildGradle);

if (failed) {
  console.log("\nDrift detected — re-run `expo prebuild --platform android` (clean, if needed) or hand-patch android/ to match.");
  process.exit(1);
} else {
  console.log("\nNo drift.");
}
